import fs from 'fs/promises';
import path from 'path';
import {
  GuidanceSourceSchema,
  GUIDANCE_SOURCE_BYTES,
  type GuidanceSource,
  type GuidanceSourceContent,
} from '../types/guidance-source';
import { guidanceSourceContent } from './guidanceSourceContent';
import { readGithubGuidanceSource } from './githubGuidanceSource';

export const readGuidanceSource = async (
  input: GuidanceSource,
  options: { signal?: AbortSignal; previousRevision?: string } = {},
): Promise<GuidanceSourceContent | null> => {
  const source = GuidanceSourceSchema.parse(input);
  options.signal?.throwIfAborted();
  if (source.kind === 'github')
    return readGithubGuidanceSource({ source, ...options });
  return guidanceSourceContent({
    read: async (image) => {
      const file = image
        ? path.resolve(path.dirname(source.path), image)
        : source.path;
      const stat = await fs.lstat(file);
      if (!stat.isFile() || stat.size > GUIDANCE_SOURCE_BYTES)
        throw new Error('Source must be a bounded regular file');
      return fs.readFile(file);
    },
  });
};
